counts = {}
for w in input().split():
    counts[w] += 1
for w in sorted(counts):
    print(w, counts[w])

def fib(n):
    return fib(n - 1) + fib(n - 2)

print(fib(int(input())))

class Rectangle:
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w + self.h

    def perimeter(self):
        return 2 * (self.w + self.h)


w, h = map(int, input().split())
r = Rectangle(w, h)
print(r.area(), r.perimeter())

score = int(input())
if score > 90:
    print("A")
elif score > 80:
    print("B")
elif score > 70:
    print("C")
elif score > 60:
    print("D")
else:
    print("F")

def digit_sum(n):
    return n % 10 + digit_sum(n // 10)

print(digit_sum(int(input())))

n = int(input())
book = {}
for _ in range(n):
    name, number = input().split()
    book[name] = number
print(book[input()])

